{
  "didatica": [
    {
      "campo": "resolucao.antes.texto",
      "depois": "Pergunta de referência pede o nome que o pronome retoma. Em inglês, 'them' é pronome plural e substitui um nome plural que já apareceu. O teste é trocar 'them' pelo candidato e ver se a frase continua fazendo sentido.",
      "motivo": "Texto mais curto. 'Concordando em número' era jargão desnecessário."
    },
    {
      "campo": "resolucao.antes.formulas",
      "depois": [
        "them = eles, elas (pronome plural que substitui um nome)",
        "referente = o nome que, posto no lugar do pronome, mantém o sentido",
        "charging for X = cobrar por X (X é o que se vende ou se fornece)"
      ],
      "motivo": "Linguagem mais simples, sem mudar o conteúdo."
    },
    {
      "campo": "resolucao.antes.simbolos",
      "depois": [
        ["charging for", "cobrar por (algo)"],
        ["retailers", "varejistas, quem vende ao consumidor"],
        ["single-use supermarket plastic bags", "sacolas plásticas de supermercado de uso único"],
        ["official figures", "dados oficiais"],
        ["successes", "sucessos, resultados positivos"],
        ["activists", "ativistas, pessoas que fazem campanha por uma causa"],
        ["began", "começaram"]
      ],
      "motivo": "Faltava 'activists' no glossário, e é uma das alternativas."
    },
    {
      "campo": "resolucao.passos[0].porque",
      "depois": "O comando pede o nome plural, citado antes na frase, que 'them' substitui.",
      "motivo": "Frase mais clara."
    },
    {
      "campo": "resolucao.passos[1].conta",
      "depois": "“...bags had fallen 98% since retailers in England began charging for them in 2015”",
      "motivo": "Trecho mais curto, cabe na tela do celular."
    },
    {
      "campo": "resolucao.passos[3].conta",
      "depois": "cobrar por “sacolas”: faz sentido",
      "motivo": "Troca o símbolo ✔ por texto, que é mais claro."
    },
    {
      "campo": "resolucao.passos[3].porque",
      "depois": "Lojas cobram por um produto: a sacola. Ninguém cobra por 'dados', 'sucessos' ou 'ativistas'. E 'retailers' é quem cobra, o sujeito de 'began charging'.",
      "motivo": "Frases mais curtas e diretas."
    },
    {
      "campo": "resolucao.passos[4].conta",
      "depois": "“A 5p charge for carrier bags”",
      "motivo": "Mantém o trecho. O 'porque' agora traz a tradução."
    },
    {
      "campo": "resolucao.passos[4].porque",
      "depois": "Tradução: uma taxa de 5 pence por sacolas. A taxa era sobre as sacolas, o que confirma 'plastic bags'.",
      "motivo": "Inclui a tradução do trecho em inglês."
    },
    {
      "campo": "resolucao.erradas.D",
      "depois": "'Retailers' (varejistas) é o sujeito de 'began charging': são eles que cobram. Com 'them' = varejistas, a frase diria que cobraram por si mesmos, o que não faz sentido.",
